SELECT     ia.ADJ_DATE AS \"Adjustment Date\",     ia.LOCATION AS \"Location ID\",     ia.LOC_TYPE AS \"Location Type\",     CASE ia.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END AS \"Location Name\",     ia.ITEM AS \"Item ID\",     im.ITEM_DESC AS \"Item Description\",     im.DEPT AS \"Department Number\",     d.DEPT_NAME AS \"Department Name\",     im.CLASS AS \"Class Number\",     im.SUBCLASS AS \"Subclass Number\",     ia.REASON AS \"Reason Code\",     rt.REASON_DESC AS \"Reason Description\",     ia.PREV_QTY AS \"Quantity Before Adjustment\",     ia.ADJ_QTY AS \"Adjusted Quantity\",     ia.PREV_QTY + ia.ADJ_QTY AS \"Quantity After Adjustment\",     ia.USER_ID AS \"Adjusted By User\",     ia.CREATE_DATETIME AS \"Created Date Time\",     ia.COMMENTS AS \"Adjustment Comments\" FROM rds_wv_inv_adj ia INNER JOIN rds_wv_item_master im ON ia.ITEM = im.ITEM LEFT JOIN rds_wv_deps d ON im.DEPT = d.DEPT LEFT JOIN rds_wv_inv_adj_reason_tl rt ON ia.REASON = rt.REASON AND rt.LANG = 1 LEFT JOIN rds_wv_store st ON ia.LOCATION = st.STORE AND ia.LOC_TYPE = 'S' LEFT JOIN rds_wv_wh wh ON ia.LOCATION = wh.WH AND ia.LOC_TYPE = 'W' WHERE ia.ADJ_DATE &gt;= ADD_MONTHS(SYSDATE, -1)</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Adjustment Date</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Type</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Name</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><ds:name>Item ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Item Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:c